// Build the question-generation prompt.
//
// Edit the wording here on the canvas. This is the node that decides what kind of
// examiner the student is preparing for.
//
// The excerpts arrive already read from Postgres under the student's own session, so RLS
// has already decided what is in here. This node must not fetch anything else.
//
// Excerpt numbering is the grounding contract: the model cites excerpts by number and the
// app maps those back to chunk ids by position. Never reorder or drop excerpts.

const body = $input.first().json.body ?? $input.first().json;
const { chunks, scope, count } = body;

if (!Array.isArray(chunks) || chunks.length === 0) {
  throw new Error('payload must include at least one chunk');
}

const wanted = Math.min(Math.max(Number(count) || 12, 3), 30);

// What the panel is actually sitting for. A student defending three chapters is at a
// proposal, and a proposal panel does not ask about findings that do not exist yet.
const SCOPES = {
  chapter: 'a single chapter review. Ask about the problem, the objectives, the scope and why this study matters.',
  proposal: 'a proposal or seminar defense covering Chapters One to Three. Ask about the problem, the gap in the literature, and above all why the chosen methodology is the right one. Do not ask about findings or conclusions - the study has not been carried out yet.',
  final: 'a final defense covering the whole project. Ask across all of it, including findings, contribution to knowledge, and limitations.',
};

const occasion = SCOPES[scope] || SCOPES.final;

const RULES = `You are an experienced external examiner on a university project defense panel. You are writing the questions you would actually ask this student in the room.\n\nThe occasion is ${occasion}\n\nYou will be given numbered excerpts from the student's own project.\n\nWrite exactly ${wanted} questions.\n\nAbsolute rules:\n- This project has already been approved by the student's supervisor. You are NOT reviewing it, marking it, correcting it or improving it. Never say anything is missing, weak, thin, unclear, or should be added. Never suggest a change. Never comment on the quality of the work.\n- Only ask a question the excerpts fully answer. If you cannot write the answer from the excerpts alone, do not ask it. Ask a different question instead.\n- Everything comes from this project. Never introduce a concept, theory, author, statistic or method that is not in the excerpts.\n\nThe mix:\n- About a third at difficulty 1: the direct opening questions a panel always asks. What are your research objectives. What problem does the study address. What is your scope. Who was your population. Students freeze on these, so they must be in the set.\n- About half at difficulty 2: why the student did what they did, answered in their own terms.\n- The rest at difficulty 3: a challenge a panel might put, still answerable from what the project already says.\n- Spread the questions across the excerpts rather than clustering on one passage.\n- Plain spoken English, the way an examiner actually talks. Do not use em dashes.\n\nThe answer field:\n- What THIS PROJECT says, in the student's own terminology, drawn only from the excerpts.\n- Write it the way the student would say it out loud in the room, not as a marking scheme.\n- Never your own opinion, and never a note about what the project does not cover.\n\nMultiple choice:\n- Also give four options for each question: the correct one plus three that are wrong but believable.\n- Distractors must sound like something this project could plausibly have said. Draw them from nearby content, a different chapter's terminology, or a common confusion in the field.\n- Never write a distractor that criticises the project or says information is absent. Never use 'none of the above', 'all of the above', or a joke option.\n- Keep all four roughly the same length. A correct answer that is visibly longer gives itself away.\n- correct is the 0-based index of the right option. Vary which position it lands in.\n\nReturn ONLY a JSON array, no prose before or after, no markdown fence:\n[{"question":"...","answer":"...","difficulty":2,"sources":[1,3],"options":["...","...","...","..."],"correct":0}]`;

const excerpts = chunks
  .map((c, i) => {
    const where = c.chapter
      ? `Chapter ${c.chapter}${c.label ? ` - ${c.label}` : ''}`
      : (c.label || 'Unlabelled section');
    return `[${i + 1}] (${where})\n${c.content}`;
  })
  .join('\n\n---\n\n');

const prompt = `${RULES}\n\nExcerpts from the project:\n\n${excerpts}`;

return [{ json: { prompt } }];

// Parse and sanitise the model's JSON.
//
// Models wrap JSON in prose or a markdown fence often enough that trusting a bare parse
// would fail intermittently, which is worse than failing always. So: find the array,
// parse it, then throw away anything malformed rather than storing half a question.

const j = $input.first().json ?? {};
const raw = j.text ?? j.response ?? j.output ?? '';

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('the model returned nothing');
}

const fenced = raw.replace(/```(?:json)?/gi, '');
const start = fenced.indexOf('[');
const end = fenced.lastIndexOf(']');

if (start === -1 || end <= start) {
  throw new Error('no JSON array in the response');
}

let parsed;
try {
  parsed = JSON.parse(fenced.slice(start, end + 1));
} catch (e) {
  throw new Error('the response was not valid JSON: ' + e.message);
}

if (!Array.isArray(parsed)) throw new Error('expected an array');

const questions = [];
for (const q of parsed) {
  if (!q || typeof q.question !== 'string' || typeof q.answer !== 'string') continue;
  if (!q.question.trim() || !q.answer.trim()) continue;

  const difficulty = Math.min(Math.max(Number(q.difficulty) || 2, 1), 3);

  // Excerpt numbers are 1-based in the prompt; hand back 0-based indexes so the app can
  // map straight into the array it sent.
  const sources = Array.isArray(q.sources)
    ? [...new Set(q.sources.map((n) => Number(n) - 1).filter((n) => Number.isInteger(n) && n >= 0))]
    : [];

  // Options are optional. A question whose choices came back malformed is still a
  // perfectly good flashcard, so it is kept without them rather than discarded.
  let options = null;
  let correct = null;
  if (Array.isArray(q.options)) {
    const cleaned = q.options.map((o) => String(o ?? '').trim()).filter(Boolean);
    const idx = Number(q.correct);
    const unique = new Set(cleaned.map((o) => o.toLowerCase()));
    if (
      cleaned.length >= 2 &&
      cleaned.length <= 5 &&
      unique.size === cleaned.length &&
      Number.isInteger(idx) &&
      idx >= 0 &&
      idx < cleaned.length
    ) {
      options = cleaned;
      correct = idx;
    }
  }

  questions.push({
    question: q.question.trim(),
    answer: q.answer.trim(),
    difficulty,
    sourceIndexes: sources,
    options,
    correct,
  });
}

if (questions.length === 0) throw new Error('no usable questions in the response');

return [{ json: { questions } }];
